async openTargetInSplit(path, objectId) {
    const file = this.app.vault.getAbstractFileByPath(path);
    if (!(file instanceof import_obsidian4.TFile))
      throw new Error(`\u672A\u627E\u5230\u6458\u5F55\u76EE\u6807\uFF1A${path}`);
    if (path.endsWith(".excalidraw.md")) {
      const excalidraw = this.excalidrawPlugin();
      if (!excalidraw)
        throw new Error("\u672A\u5B89\u88C5 Excalidraw \u63D2\u4EF6\uFF0C\u65E0\u6CD5\u5728\u539F\u751F\u76EE\u6807\u9762\u677F\u6253\u5F00\u8BE5\u6458\u5F55\u3002");
      await excalidraw.openDrawing(file, "new-pane", true);
      if (objectId)
        this.scheduleNativeFocus(objectId);
      return;
    }
    const leaf = this.app.workspace.getLeaf("split");
    await leaf.openFile(file);
    this.app.workspace.setActiveLeaf(leaf, { focus: true });
    if (objectId)
      this.scheduleNativeFocus(objectId, leaf.view);
  }
